// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";

import {
  mergedBranchWarning,
  mostRecentPullRequest,
} from "./merged-branch-warning.mjs";

// gaps.d/a-branch-whose-pr-merged-can-still-take-commits.md: neither the task
// ledger nor local git state can see GitHub, so a branch whose PR already
// merged looked exactly like one that never had a PR at all. `capture` is
// injected so these never spawn a real `gh` process.

test("a branch with no pull request is checked and reports none", () => {
  const result = mostRecentPullRequest({
    branch: "feat/example",
    capture: () => "[]",
  });
  assert.deepEqual(result, { checked: true, pullRequest: null });
});

test("the highest PR number wins regardless of the order gh returns them in", () => {
  const result = mostRecentPullRequest({
    branch: "feat/example",
    capture: () =>
      JSON.stringify([
        { number: 414, state: "CLOSED", url: "https://example/pulls/414" },
        { number: 418, state: "MERGED", url: "https://example/pulls/418" },
        { number: 3, state: "OPEN", url: "https://example/pulls/3" },
      ]),
  });
  assert.deepEqual(result, {
    checked: true,
    pullRequest: {
      number: 418,
      state: "MERGED",
      url: "https://example/pulls/418",
    },
  });
});

test("gh being unavailable or unauthenticated degrades to unchecked, not a throw", () => {
  const result = mostRecentPullRequest({
    branch: "feat/example",
    capture: () => {
      throw new Error("gh: command not found");
    },
  });
  assert.deepEqual(result, { checked: false, pullRequest: null });
});

test("malformed gh output degrades to unchecked rather than crashing", () => {
  const result = mostRecentPullRequest({
    branch: "feat/example",
    capture: () => "not json",
  });
  assert.deepEqual(result, { checked: false, pullRequest: null });
});

test("no warning when the branch has never had a pull request", () => {
  const warning = mergedBranchWarning({
    branch: "feat/example",
    checked: true,
    pullRequest: null,
  });
  assert.equal(warning, null);
});

test("no warning when the most recent pull request is still open", () => {
  const warning = mergedBranchWarning({
    branch: "feat/example",
    checked: true,
    pullRequest: {
      number: 418,
      state: "OPEN",
      url: "https://example/pulls/418",
    },
  });
  assert.equal(warning, null);
});

test("no warning when the most recent pull request was closed without merging", () => {
  const warning = mergedBranchWarning({
    branch: "feat/example",
    checked: true,
    pullRequest: {
      number: 418,
      state: "CLOSED",
      url: "https://example/pulls/418",
    },
  });
  assert.equal(warning, null);
});

test("a merged pull request is named in the warning, with the fresh-PR remedy", () => {
  const warning = mergedBranchWarning({
    branch: "feat/example",
    checked: true,
    pullRequest: {
      number: 418,
      state: "MERGED",
      url: "https://example/pulls/418",
    },
  });
  assert.match(warning, /feat\/example/);
  assert.match(warning, /#418, https:\/\/example\/pulls\/418/);
  assert.match(warning, /gh pr create --head feat\/example/);
});

test("an unchecked result still warns, naming the degradation", () => {
  const warning = mergedBranchWarning({
    branch: "feat/example",
    checked: false,
    pullRequest: null,
  });
  assert.match(warning, /could not check GitHub/);
  assert.match(warning, /pushing anyway/);
});
